mapper.select:
SELECT o.id, o.outbound_no, o.warehouse_id, o.status, o.remark, o.confirmed_at, o.operator, o.version, o.created_at, o.updated_at, w.warehouse_code, w.name AS warehouse_name FROM inventory_outbound o LEFT JOIN warehouse w ON w.id = o.warehouse_id WHERE o.deleted = FALSE
AND o.outbound_no ILIKE CONCAT('%', #{query.outboundNo}, '%')
AND o.warehouse_id = #{query.warehouseId}
AND o.status = #{query.status}
ORDER BY o.created_at DESC, o.id DESC
